// `Env` is generated by `npm run types` into worker-configuration.d.ts as a global interface.
// Secrets are not in wrangler.jsonc, so they are declared here and merged into it.
// Set them in `.dev.vars` locally, or with `wrangler secret put` for the deployed Worker.
declare global {
	interface Env {
		/** Guards the admin and dispatch routes. */
		ADMIN_TOKEN?: string;
		/** Only needed when LLM="anthropic". */
		ANTHROPIC_API_KEY?: string;
	}
}

export type { Env };

type Env = globalThis.Env;
